import{_ as i,o as t,c as r,a3 as n}from"./chunks/framework.BlfGB29P.js";const b=JSON.parse('{"title":"Entity-Picture-Override deaktivieren","description":"Overrides für Entitätsbilder deaktivieren.","frontmatter":{"title":"Entity-Picture-Override deaktivieren","description":"Overrides für Entitätsbilder deaktivieren."},"headers":[],"relativePath":"projects/uix/extras/disable-entity-picture-image-override.md","filePath":"projects/uix/extras/disable-entity-picture-image-override.md","lastUpdated":1793108161000}'),a={name:"projects/uix/extras/disable-entity-picture-image-override.md"};function d(o,e,s,l,c,u){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="entity-picture-image-overrides-deaktivieren" tabindex="-1">Entity-Picture-Image-Overrides deaktivieren <a class="header-anchor" href="#entity-picture-image-overrides-deaktivieren" aria-label="Permalink to &quot;Entity-Picture-Image-Overrides deaktivieren&quot;">​</a></h1><p>Diese Option verhindert, dass UIX Entitätsbilder ersetzt. Das ist nützlich, wenn eine Karte, Integration oder Kamera eigene Bildlogik nutzt und UIX diese Bilder nicht überschreiben soll.</p><h2 id="einstellung-uber-die-integrations-ui" tabindex="-1">Einstellung über die Integrations-UI <a class="header-anchor" href="#einstellung-uber-die-integrations-ui" aria-label="Permalink to &quot;Einstellung über die Integrations-UI&quot;">​</a></h2><ol><li>In Home Assistant zu <strong>Settings -&gt; Devices &amp; Services -&gt; UI eXtension -&gt; Configure</strong> gehen.</li><li>Den passenden Optionsbereich öffnen.</li><li><strong>Disable entity picture image overrides</strong> aktivieren.</li><li>Speichern.</li></ol><h2 id="verhalten-bei-aktivierter-option" tabindex="-1">Verhalten bei aktivierter Option <a class="header-anchor" href="#verhalten-bei-aktivierter-option" aria-label="Permalink to &quot;Verhalten bei aktivierter Option&quot;">​</a></h2><ul><li>UIX wendet <code>--uix-image</code> und <code>--uix-image-for-&lt;entity_id&gt;</code> nicht mehr als Bild-Override an.</li><li>Bestehende Kartenbilder und Entitätsbilder bleiben unverändert.</li><li>Andere UIX-Styling- und Theme-Funktionen bleiben verfügbar.</li></ul><h2 id="betroffene-elemente-und-css-variablen" tabindex="-1">Betroffene Elemente und CSS-Variablen <a class="header-anchor" href="#betroffene-elemente-und-css-variablen" aria-label="Permalink to &quot;Betroffene Elemente und CSS-Variablen&quot;">​</a></h2><p>Die standardmäßig nicht gesetzte Option wirkt nach dem Speichern sofort auf alle verbundenen Browser, ohne Neuladen. Sie deaktiviert das Patching für <code>ha-entity-marker</code>, <code>ha-tile-icon</code>, <code>state-badge</code>, <code>ha-user-badge</code> und <code>ha-person-badge</code>. Die Bildüberschreibungen über <code>--uix-image</code> und <code>--uix-image-for-*</code> werden dann nicht mehr auf diese Badges und Marker angewendet.</p>',8)])])}const g=i(a,[["render",d]]);export{b as __pageData,g as default};
